window.piAirbnbCaptchaClick = async function (ev) {
  var id = window._piAirbnbLoginId;
  var img = ev && ev.currentTarget;
  if (!id || !img) return;
  var rect = img.getBoundingClientRect();
  var naturalW = img.naturalWidth || 1440;
  var naturalH = img.naturalHeight || 900;
  var x = Math.round((ev.clientX - rect.left) * naturalW / rect.width);
  var y = Math.round((ev.clientY - rect.top) * naturalH / rect.height);
  img.style.opacity = '0.55';
  try {
    var res = await fetch('/api/platform-invoices/sessions/airbnb/login/' +
      encodeURIComponent(id) + '/captcha/click', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ x: x, y: y })
      });
    var j = await res.json();
    if (!res.ok && !(j && j.job)) throw new Error((j && j.error) || 'Picture-check click failed');
    if (j.job) piRenderAirbnbConnect(j.job);
    if (j.job && j.job.status === 'awaiting_captcha') {
      msg('Click registered — continue the picture check, then click Verify inside the image', true);
    } else if (j.job && j.job.status === 'awaiting_otp') {
      msg('Picture check passed — enter the email code', true);
    } else if (j.job && j.job.status === 'connected') {
      msg('Airbnb connected in-app', true);
      await piReload();
    } else if (!res.ok) {
      throw new Error(j.error || 'Picture check failed');
    }
  } catch (e) {
    msg(e.message || String(e), false);
    if (img) img.style.opacity = '1';
  }
};
